        var inspector=Field<VBoxContainer>(o,"inspector");clear(inspector);if(Dict(o,"_library_entry").Count>0){o.Call("_generator_inspector");return;}var session=Session(o);var actor=session.Call("primary_actor").AsGodotObject();var clip=session.Call("primary_clip").AsGodotObject();var track=Document(o).Call("track_for_id",session.Get("selected_track")).AsGodotDictionary();using var lanes=new AudioAutomationLaneOperations();if(actor==null&&lanes.is_lane(track)){o.Call("_automation_lane_inspector",track);return;}if(Get(track,"locked",false).AsBool()){if(track.ContainsKey("frozen_track")||track.ContainsKey("frozen_source")){heading(inspector,"Frozen track");label(inspector,"The source notes and processing remain recoverable. Unfreeze to edit them.");ActionButton(inspector,"Unfreeze track",()=>o.Call("unfreeze_track"));}else{heading(inspector,"Track locked");label(inspector,"Unlock this track to edit its clips and instrument data.");ActionButton(inspector,"Unlock",()=>SessionAction(o,"Unlock track",()=>track["locked"]=false));}return;}
        if(actor!=null&&clip!=null)
        {
            var values=actor.Get("values").AsGodotDictionary();heading(inspector,"Clip · "+actor.Get("display_name").AsString());var input=new LineEdit{Text=actor.Get("display_name").AsString()};inspector.AddChild(input);input.TextSubmitted+=value=>SessionAction(o,"Rename clip",()=>actor.Set("display_name",value));NumberAction(o,inspector,"Start (s)",clip.Get("start_time").AsDouble(),0,86400,.00001,value=>EditAction(o,"Move clips",()=>Session(o).Call("move_selected",value-clip.Get("start_time").AsDouble())));NumberAction(o,inspector,"Duration (s)",clip.Get("duration").AsDouble(),.00001,86400,.00001,value=>EditAction(o,"Trim clip",()=>Session(o).Call("edit_clip",clip.Get("id"),new Settings{["duration"]=value})));NumberAction(o,inspector,"Source offset",clip.Get("source_offset").AsDouble(),0,86400,.00001,value=>EditAction(o,"Slip clip",()=>Session(o).Call("edit_clip",clip.Get("id"),new Settings{["source_offset"]=value})));NumberAction(o,inspector,"Gain (dB)",Get(values,"volume_db",0).AsDouble(),-60,24,.1,value=>EditAction(o,"Clip gain",()=>Session(o).Call("set_clip_value",new StringName("volume_db"),value)));NumberAction(o,inspector,"Pan",Get(values,"pan",0).AsDouble(),-1,1,.01,value=>EditAction(o,"Clip pan",()=>Session(o).Call("set_clip_value",new StringName("pan"),value)));NumberAction(o,inspector,"Speed",clip.Get("playback_speed").AsDouble(),.05,16,.01,value=>EditAction(o,"Stretch clip",()=>Session(o).Call("edit_clip",clip.Get("id"),new Settings{["playback_speed"]=value,["duration"]=clip.Get("duration").AsDouble()*clip.Get("playback_speed").AsDouble()/value})));NumberAction(o,inspector,"Pitch (semi)",12*Math.Log(Math.Max(.01,Get(values,"pitch",1).AsDouble()))/Math.Log(2),-36,36,.1,value=>EditAction(o,"Clip pitch",()=>Session(o).Call("set_clip_value",new StringName("pitch"),Math.Pow(2,value/12))));foreach(string field in new[]{"fade_in","fade_out"})NumberAction(o,inspector,field.Capitalize()+" (s)",Get(values,field,0).AsDouble(),0,clip.Get("duration").AsDouble(),.00