        {
            heading(inspector,"Track · "+track["name"].AsString());var input=new LineEdit{Text=track["name"].AsString()};inspector.AddChild(input);input.TextSubmitted+=value=>SessionAction(o,"Rename track",()=>track["name"]=value);var color=new ColorPickerButton{Color=Get(track,"color",new Color("63d9bc")).AsColor(),CustomMinimumSize=new Vector2(0,24),TooltipText="Track color"};inspector.AddChild(color);var colorSession=Session(o);var colorDocument=Document(o) as RefCounted;color.ColorChanged+=value=>{if(!mixer_context_current(o,color,colorSession,colorDocument!))return;var previous=o.Get("_edit_control_id");o.Set("_edit_control_id",color.GetInstanceId());try{EditAction(o,"Track color",()=>track["color"]=value);}finally{o.Set("_edit_control_id",previous);}};NumberAction(o,inspector,"Volume (dB)",Get(track,"volume_db",0).AsDouble(),-60,12,.1,value=>EditAction(o,"Track volume",()=>track["volume_db"]=value));NumberAction(o,inspector,"Pan",Get(track,"pan",0).AsDouble(),-1,1,.01,value=>EditAction(o,"Track pan",()=>track["pan"]=value));var destinations=new GArray{"Master"};var ids=new GArray{""};foreach(var raw in Items(Document(o),"tracks")){var other=raw.AsGodotDictionary();if(other["id"].AsString()!=track["id"].AsString()&&!lanes.is_lane(other)){destinations.Add(other["name"].AsString());ids.Add(other["id"].AsString());}}int current=ids.IndexOf(Get(track,"output","").AsString());ChoiceAction(o,inspector,"Output",destinations,destinations[Math.Max(0,current)].AsString(),value=>SessionAction(o,"Route track",()=>{if(!Session(o).Call("set_track_value",track["id"],"output",ids[destinations.IndexOf(value)]).AsBool())notice(o,"That routing would create a feedback loop.");}));foreach(var entry in new[]{("Add send\u2026","send_dialog"),("Add automation point\u2026","automation_dialog"),("Track takes\u2026","take_dialog"),("Freeze track","freeze_track"),("Bounce track","bounce_track")})ActionButton(inspector,entry.Item1,()=>o.Call(entry.Item2));ActionButton(inspector,"Delete tra