    }
    public void instrument_inspector(Control o,GodotObject actor,Settings track)
    {
        var inspector=Field<VBoxContainer>(o,"inspector");var values=actor.Get("values").AsGodotDictionary();heading(inspector,"Instrument");if(values.ContainsKey(new StringName("midi_tempos")))label(inspector,"MIDI source tempo map active. Conductor edits preserve this source timing. Uniform retime explicitly scales it; the timeline grid and metronome use the project conductor.");else if(values.ContainsKey(new StringName("midi_events")))label(inspector,"This older MIDI source uses the saved source BPM. Reimport the original MIDI to restore its source tempo-map playback.");if(!values.ContainsKey(new StringName("midi_tempos"))){using var edits=new AudioEditSessionOperations();label(inspector,"Source timing: "+edits.note_source_tempo(actor,Document(o)).ToString("F2",CultureInfo.InvariantCulture)+" BPM. Conductor edits leave these source-relative note beats unchanged.");}if(values.ContainsKey(new StringName("midi_events"))){var sustain=CheckAction(inspector,"Render MIDI sustain pedal (CC64)",Get(values,"midi_sustain",false).AsBool(),value=>{if(Get(track,"locked",false).AsBool()||track.ContainsKey("frozen_track"))return;SessionAction(o,"MIDI sustain rendering",()=>{values[new StringName("midi_sustain")]=value;values[new StringName("notes_dirty")]=true;});o.Call("_render_dirty_notes");});sustain.Disabled=Get(track,"locked",false).AsBool()||track.ContainsKey("frozen_track");label(inspector,"Optional CC64 sustain extends rendered note gates until pedal-up or the source pattern end. Same-beat controller state is applied before note-off. Source notes and MIDI export stay unchanged; one-shot/drum or monophonic patches may ignore/restrict long gates. Half-pedaling and other MIDI controllers are not performed.");}
        using var instruments=new AudioInstrumentOperations();var patch=Get(values,"instrument",Get(track,"instrument",new Settings{["id"]="poly"})).AsGodotDictionary();if(patch.Count<3)patch=instruments.default_instrument(Get(patch,"id","poly").AsString());var ids=new GArray();var labels=new GArray();foreach(var preset in instruments.presets()){ids.Add(preset["id"]);labels.Add(preset["label"]);}int index=ids.IndexOf(patch["id"].AsString());ChoiceAction(o,inspector,"Patch",labels,labels[Math.Max(0,index)].AsString(),value=>{SessionAction(o,"Change instrument",()=>{using var presets=new AudioInstrumentOperations();values[new StringName("instrument")]=presets.default_instrument(ids[labels.IndexOf(value)].AsString());values[new StringName("notes_dirty")]=true;});o.Call("_render_dirty_notes");});foreach(var info in new[]{("attack",.0005,10.0,.001),("decay",.001,10.0,.01),("sustain",0.0,1.0,.01),("release",.003,10.0,.01),("filter",20.0,20000.0,1.0),("resonance",0.0,.95,.01),("detune",0.0,40.0,.1),("modulation",0.0,8.0,.01),("vibrato",0.0,1.0,.01),("width",0.0,1.0,.01)}){string key=info.Item1;NumberAction(o,inspector,key.Capitalize(),Get(patch,key,0).AsDouble(),info.Item2,info.Item3,info.Item4,value=>{EditAction(o,"Instrument settings",()=>{patch[key]=value;values[new StringName("instrument")]=patch;values[new StringName("notes_dirty")]=true;});Field<Timer>(o,"_preview_timer").Stop();});}ActionButton(inspector,"Render instrument changes",()=>o.Call("_render_dirty_notes"));ActionButton(inspector,"Instrument modulation",()=>o.Call("modulator_dialog",false));string kind=Get(patch,"kind","").AsString();if(kind is "sampler" or "multisample"){ActionButton(inspector,"Choose sample",()=>o.Call("choose_instrument_sample"));NumberAction(o,inspector,"Root MIDI note",Get(patch,"root_pitch",60).AsDouble(),0,127,1,value=>EditAction(o,"Sampler root",()=>{patch["root_pitch"]=(int)value;values[new StringName("instrument")]=patch;values[new StringName("notes_dirty")]=true;}));CheckAction(inspector,"Loop sample",Get(patch,"loop",false).AsBool(),value=>SessionAction(o,"Sample looping",()=>{patch["loop"]=value;values[new StringName("instrument")]=patch;values[new StringName("notes_dirty")]=true;}));foreach(string key in new[]{"loop_start","loop_end"})NumberAction(o,inspector,key,Get(patch,key,key=="loop_start"?0:-1).AsDouble(),-1,300,.001,value=>EditAction(o,"Sample loop points",()=>{patch[key]=value;values[new StringName("instrument")]=patch;values[new StringName("notes_dirty")]=true;}));label(inspector,"Loop end \u22121 uses the sample end. Sampler presets preserve their sample reference and stereo channels.");if(kind=="multisample")ActionButton(inspector,"Edit sample map",()=>o.Call("sample_map_dialog"));}ActionButton(inspector,"Save instrument preset",()=>o.Call("save_preset","instrument"));Settings note=new();foreach(var raw in Get(values,"notes",new GArray()).AsGodotArray()){var candidate=raw.AsGodotDictionary();string id=candidate["id"].AsString();if(Items(Field<Control>(o,"piano"),"selected").Contains(id)||Items(Field<Control>(o,"steps"),"selected").Contains(id)){note=candidate;break;}}if(note.Count>0){heading(inspector,"Selected Note");foreach(var info in new[]{("velocity",.01,1.0,.01),("probability",0.0,1.0,.01),("ratchets",1.0,8.0,1.0),("pan",-1.0,1.0,.01)}){string key=info.Item1;NumberAction(o,inspector,key.Capitalize(),Get(note,key,1).AsDouble(),info.Item2,info.Item3,info.Item4,value=>EditAction(o,"Edit note",()=>{note[key]=value;values[new StringName("notes_dirty")]=true;}));}CheckAction(inspector,"Accent",Get(note,"accent",false).AsBool(),value=>SessionAction(o,"Note accent",()=>{note["accent"]=value;values[new StringName("notes_dirty")]=true;}));CheckAction(inspector,"Mute note",Get(note,"mute",false).AsBool(),value=>SessionAction(o,"Mute note",()=>{note["mute"]=value;values[new StringName("notes_dirty")]=true;}));}
    }
